insert into seed_requests values
  ('PR-001', 'drawings@ersupplies.co.za', true, 'Hi Grade Spring', 'admin@higradespring.co.za', 'Spring, 3mm stainless spring wire, 17 coils, 12.5 ID, 383 long, dwg ER-DRG-01 P-001', '60', 'QU025743 (10/03/2023, R61.50 ea @ 60)', 'Reply', '2026-10-15', '2026-10-16', 0, 'Asked spring temper, grade named by them, prefer 301. Quote QU043638 2026-10-16: 301 not available, offer 3mm ST/ST grade 302, 12.5 ID, 2x 17 ID hooks, 370 ctc (drawing says 383 long, check). R88.40 ea x60 = R5,304.00 ex VAT (R6,099.60 incl), lead 5-7 working days. Quote, not a pro forma: needs your OK on GR 302, then ask for pro forma', 'AAkALgAAAAAAHYQDEapmEc2byACqAC-EWg0Ao0BjD_nnZUemANZccbnMXAAHpUFkJgAA'),
  ('PR-002', 'drawings@ersupplies.co.za', true, 'Eurosteel', 'TashS@eurosteel.co.za', '50mm 304 SS round bar, cut to 1000mm', '1', 'EJBOPP222757 (22/02/2023, thread only)', 'Closed', '2026-10-15', null, 0, 'Price comparison with PR-003 (NDE). Contact is from 2023, may have left: 011 383 0300. Sent with no subject line. Quote EJBOPP449418 2026-10-15: R948.00 ex VAT (R1,090.20 incl), 304, approx 3 working days, valid 7 days. On account EAS007, order on the quote. R34.94 cheaper than NDE', 'AAkALgAAAAAAHYQDEapmEc2byACqAC-EWg0Ao0BjD_nnZUemANZccbnMXAAHpUFoKAAA'),
  ('PR-003', 'drawings@ersupplies.co.za', true, 'NDE', 'dineo@nde.co.za', '50mm 304 SS round bar, cut to 1000mm', '1', 'QTEJB226442 (28/04/2026, thread only)', 'Closed', '2026-10-15', null, 0, 'Price comparison with PR-002 (Euro Steel). Quote QTEJB284237 2026-10-15: R982.94 ex VAT (R1,130.38 incl), 304L, ex stock, valid 7 days. Account EAS011', 'AAkALgAAAAAAHYQDEapmEc2byACqAC-EWg0Ao0BjD_nnZUemANZccbnMXAAHpUFoLwAA'),
  ('PR-004', 'drawings@ersupplies.co.za', true, 'McNaughtan', 'salesrep@mcnaughtan.co.za', 'Gas strut, series 4100 (10mm rod), 1200mm long. New item', '2', 'none (new item)', 'Reply', '2026-10-15', '2026-10-15', 0, 'Asked them to advise force options, end fittings and lead time. COD. Quote 10896324 2026-10-15 from Stephen Meselane (jhbsales4@mcnaughtan.co.za, 011 334 1630): 1200mm 100N out of stock, offers K4153-350NDC pre-pumped 350N with dust cover, R280 ea x2 + 4 end fittings K258251 R15 ea = R620.00 ex VAT (R713.00 incl). No lead time given. CHECK: quote line reads 1000MM vs 1200mm asked, and 350N. COD037: pay by EFT using ref 10896324', 'AAkALgAAAAAAHYQDEapmEc2byACqAC-EWg0Ao0BjD_nnZUemANZccbnMXAAHpUGRwAAA'),
  ('PR-005', 'sales@ersupplies.co.za', false, 'ElectroMechanica', 'sales@em.co.za', 'Wash bay control panel parts: interlock switch, TMM1 timer, E-stop, pilot lights, plus enclosure hardware, breakers, contactors, VSD 0.37 kW, push buttons, field devices, panel wire (54-line list)', 'see list', 'QUGE97534 (2026-10-07)', 'Pro forma', '2026-10-07', null, 0, 'Found in sweep. Sent by Gawie from sales@ersupplies.co.za, you added items 2026-10-07. Pro forma QUGE97534 2026-10-07 for items 1-5, ETA 3-5 days after payment, pay ref QUGE97534. Revised quote Estimate 41401495 2026-10-07 with everything; EM does not supply cables and wires. PDFs not readable by the connector: totals not checked', 'AAMkAGE3Mzk2NmQ4LWQ5OWYtNDZhNi1iZTdlLTRiMGRkY2ZkY2M4YQBGAAAAAABbz6nQK60_Sb4z-CwyRI9EBwCjQGMP6edlR6YA1lxxucxcAAAAAAEJAACjQGMP6edlR6YA1lxxucxcAAbGnYUVAAA='),
